Lemma geo_1RB0RD_1LC1RA_0RB0LD_0RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_1LC1RA_0RB0LD_0RB0LC) = lift (Cc (Pos.succ p)).
