  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S0;S1]))).
  { unfold Cc_1RB0RD_1LC1RA_0RB0LD_0RB0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
