  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RD_1LC1RA_0RB0LD_0RB0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RD_1LC1RA_0RB0LD_0RB0LC B0_1RB0RD_1LC1RA_0RB0LD_0RB0LC B1_1RB0RD_1LC1RA_0RB0LD_0RB0LC 4 6 p j' [] []).
    + exact run_ovf_1RB0RD_1LC1RA_0RB0LD_0RB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RD_1LC1RA_0RB0LD_0RB0LC p j' E).
    + exact (geo_1RB0RD_1LC1RA_0RB0LD_0RB0LC p j' E).
    + lia.
Qed.

