(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RD_1LC1RA_0RB0LD_0RB0LC : existsb (fun tg => cfires tmm_1RB0RD_1LC1RA_0RB0LD_0RB0LC c0 10 tg) pins_1RB0RD_1LC1RA_0RB0LD_0RB0LC = true.
