(** 1RB0RD_1RC1LB_1LD1RA_0RC0LD *)
(** 1RB0RD_1RC1LB_1LD1RA_0RC0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RD_1RC1LB_1LD1RA_0RC0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DR StC | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB0LD_1LC1RB_1RD1LA_0LC0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RD_1RC1LB_1LD1RA_0RC0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S0 DL StC | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RD_1RC1LB_1LD1RA_0RC0LD : list Instr := [(StA, S1); (StB, S1)].
Definition tmw_1RB0RD_1RC1LB_1LD1RA_0RC0LD : TM := tm_wrap_trs tmm_1RB0RD_1RC1LB_1LD1RA_0RC0LD pins_1RB0RD_1RC1LB_1LD1RA_0RC0LD.
Local Notation tm := tmw_1RB0RD_1RC1LB_1LD1RA_0RC0LD.

Lemma mirror_ok_1RB0RD_1RC1LB_1LD1RA_0RC0LD : mirror_tm tm_1RB0RD_1RC1LB_1LD1RA_0RC0LD = tmm_1RB0RD_1RC1LB_1LD1RA_0RC0LD.
Proof.
  apply functional_extensionality; intro q;
