Lemma geo_1RB1LA_0RC0RB_1LC1LD_0LA___ : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0RC0RB_1LC1LD_0LA___) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0RC0RB_1LC1LD_0LA___
             = (StB, (rep [S0] (S j) ++ [S1], S0, [S1;S1;S1]))).
  { unfold cden, B1_1RB1LA_0RC0RB_1LC1LD_0LA___, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S1;S1]))).
  { unfold Cc_1RB1LA_0RC0RB_1LC1LD_0LA___. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_0RC0RB_1LC1LD_0LA___. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1LA_0RC0RB_1LC1LD_0LA___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0RC0RB_1LC1LD_0LA___ p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0RC0RB_1LC1LD_0LA___ B0_1RB1LA_0RC0RB_1LC1LD_0LA___ B1_1RB1LA_0RC0RB_1LC1LD_0LA___ 2 6 p j' [] []).
    + exact run_ovf_1RB1LA_0RC0RB_1LC1LD_0LA___.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0RC0RB_1LC1LD_0LA___ p j' E).
    + exact (geo_1RB1LA_0RC0RB_1LC1LD_0LA___ p j' E).
    + lia.
Qed.

